PAGES = {'index':('Главная',home),'about':('Что такое Малмыжское месторождение',about),'location':('Где находится месторождение',location),'resources':('Что добывают на месторождении',resources),'importance':('Почему месторождение важно',importance),'ecology':('Экология Хабаровского края',ecology),'sources':('Источники и изображения',sources_page)}

def render(slug):
    title,body=PAGES[slug]
    nav=''.join(f'<a href="{key}.html"'+(' aria-current="page"' if key==slug else '')+f'>{name}</a>' for key,name in NAV)
    return f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f8f2"><meta name="description" content="Малмыжское месторождение: география, медь, золото, значение для Хабаровского края и экологические вопросы. Учебный проект с проверяемыми источниками."><title>{title} — Малмыж</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/site.js" defer></script></head>
<body><a class="skip-link" href="#main">К содержанию</a><header class="site-header"><div class="header-inner"><a class="brand" href="index.html" aria-label="Малмыж — главная"><svg viewBox="0 0 44 44" aria-hidden="true"><path d="M3 32 15 10l7 13 6-10 13 23H3Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="m9 30 6-11 7 13 6-9 7 10" fill="none" stroke="#b57850" stroke-width="2"/></svg><span>Малмыж<small>АТЛАС МЕСТОРОЖДЕНИЯ</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav">Меню <span aria-hidden="true">☰</span></button><nav id="site-nav" aria-label="Основная навигация">{nav}</nav><a class="header-sources" href="sources.html" {'aria-current="page"' if slug=='sources' else ''}>Источники {ARROW}</a></div></header><main id="main" class="container {'home' if slug=='index' else ''}">{'' if slug=='index' else '<nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="index.html">Главная</a><span>/</span><span>'+title+'</span></nav>'}{body()}</main><footer class="site-footer"><div class="container footer-inner"><div><a class="footer-brand" href="index.html">Малмыж<span> / Хабаровский край</span></a><p>Геология. Люди. Природа.<br>Учебный информационный проект.</p></div><div><a href="sources.html">Источники и изображения ↗</a><p>Проверка материалов: {CHECKED}<br>Неофициальный сайт · Создан на Python</p></div></div></footer></body></html>'''

def build(destination=DIST):
    destination.mkdir(parents=True,exist_ok=True)
    shutil.copytree(ROOT/'assets',destination/'assets',dirs_exist_ok=True)
    for slug in PAGES:(destination/f'{slug}.html').write_text(render(slug),encoding='utf-8')
    (destination/'.nojekyll').touch()
    (destination/'404.html').write_text(render('index').replace('<h1>Малмыж.', '<p class="not-found">Такой страницы нет. Начните с главной.</p><h1>Малмыж.'),encoding='utf-8')
    return destination

class Handler(SimpleHTTPRequestHandler):
    def do_GET(self):
        # Страницы создаются Python при каждом открытии; остальные файлы отдаются как статика.
        slug=self.path.split('?',1)[0].strip('/').removesuffix('.html') or 'index'
        if slug in PAGES:
            content=render(slug).encode('utf-8')
            self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(content)));self.end_headers();self.wfile.write(content)
        else:super().do_GET()

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command',choices=['build','serve','check'],nargs='?',default='serve')
    parser.add_argument('--port',type=int,default=8000)
    args=parser.parse_args()
    if args.command=='build':print(f'Собрано {len(PAGES)} страниц: {build()}')
    elif args.command=='check':
        import check_site
        check_site.check()
    else:
        server=ThreadingHTTPServer(('127.0.0.1',args.port),functools.partial(Handler,directory=str(ROOT)))
        print(f'Малмыж: http://127.0.0.1:{args.port}',flush=True)
        try:server.serve_forever()
        except KeyboardInterrupt:server.server_close()

if __name__=='__main__':main()
